import { buildAbilityLookup, buildItemLookup, buildMoveLookup } from "./catalog.js";
import { selectChampionsCatalogs } from "./web-catalogs.js";

// Slim, minified browser catalogs generated by `npm run build-web-catalogs` from the full
// public/*.json catalogs (see src/data/web-catalogs.js).
export const WEB_CATALOG_BASE = "./public/web/";

export async function loadPokemonData() {
  const [pokemonResponse, abilitiesResponse, movesResponse, itemsResponse] = await Promise.all([
    fetch(`${WEB_CATALOG_BASE}pokemon.json`),
    fetch(`${WEB_CATALOG_BASE}abilities.json`),
    fetch(`${WEB_CATALOG_BASE}moves.json`),
    fetch(`${WEB_CATALOG_BASE}items.json`),
  ]);

  for (const response of [pokemonResponse, abilitiesResponse, movesResponse, itemsResponse]) {
    if (!response.ok) throw new Error(`Data request failed: ${response.status}`);
  }

  const [pokemon, abilities, moves, items] = await Promise.all([
    pokemonResponse.json(),
    abilitiesResponse.json(),
    movesResponse.json(),
    itemsResponse.json(),
  ]);
  // The slim files are already filtered; re-applying the (idempotent) selection keeps the loader
  // correct if it is ever pointed at the full catalogs.
  const selected = selectChampionsCatalogs({ pokemon, abilities, moves, items });

  return {
    ...selected,
    abilityLookup: buildAbilityLookup(selected.abilities),
    itemLookup: buildItemLookup(selected.items),
    moveLookup: buildMoveLookup(selected.moves),
  };
}
